root='F:\AER_RETRA_CASE'; addpath(genpath(root)); day=fullfile(root,'CCN_FULL_RERUN_20260821','day_20220601'); ds=dir(fullfile(day,'orbit_*','CALIPSO_results_2022_06_01_hdf.mat')); A=load(fullfile(ds(3).folder,ds(3).name),'T_all'); T=A.T_all; good=isfinite(T.Ext)&T.Ext>0&isfinite(T.Back)&T.Back>0&isfinite(T.Depol)&T.Depol>0.05&T.Depol<0.31&isfinite(T.RH)&T.RH>0&T.RH<100&isfinite(T.Type)&T.Type>=1&T.Type<=7; T=T(good,:); P0=load(which('Parameter_Particle_CALISPO.mat')); P=P0.data; E0=load(which('Extinction_Normalized.mat')); E=E0.Extinction_N; [N1,~]=Calc_Nd_OMCAM(T,P,struct('Extinction_N',E)); T.Ext=T.Ext*1e-3; T.Back=T.Back*1e-3; [N2,~]=Calc_Nd_OMCAM(T,P,struct('Extinction_N',E)); fid=fopen(fullfile(day,'unit_sensitivity.txt'),'w'); fprintf(fid,'original max=%g p99=%g mean=%g\n',max(N1),prctile(N1,99),mean(N1)); fprintf(fid,'scaled_1e-3 max=%g p99=%g mean=%g\n',max(N2),prctile(N2,99),mean(N2)); fprintf(fid,'ratio_max=%g\n',max(N2)/max(N1)); fclose(fid);
